<div id="resultEntryAudit" style="font-family:Segoe UI,Arial,sans-serif;padding:16px;color:#18233b">
<style>
#resultEntryAudit *{box-sizing:border-box}#resultEntryAudit .rea-head{padding:20px;border-radius:12px;background:linear-gradient(115deg,#172554,#4338ca,#8b5cf6);color:white;margin-bottom:12px}#resultEntryAudit h2{margin:0 0 6px;color:white;font-size:24px}#resultEntryAudit .rea-head p{margin:0;color:#e0e7ff;font-size:13px}#resultEntryAudit .rea-tools{display:flex;gap:8px;flex-wrap:wrap;padding:12px;border:1px solid #e6ebf4;background:white}#resultEntryAudit input{padding:10px;border:1px solid #dfe5f0;border-radius:8px;flex:1;min-width:190px}#resultEntryAudit button{padding:9px 12px;border:1px solid #dfe5f0;border-radius:8px;background:white;cursor:pointer}#resultEntryAudit .rea-table{overflow:auto;border:1px solid #e6ebf4;background:white}#resultEntryAudit table{width:100%;min-width:1100px;border-collapse:collapse;font-size:12px}#resultEntryAudit th{background:#f7f8fc;text-align:left;padding:11px;color:#6c7890;font-size:10px;text-transform:uppercase}#resultEntryAudit td{padding:11px;border-top:1px solid #edf0f6;overflow-wrap:anywhere;max-width:320px;vertical-align:top}#resultEntryAudit .rea-footer{display:flex;justify-content:space-between;padding:12px;border:1px solid #e6ebf4;background:#fcfcfe;font-size:12px}#resultEntryAudit .rea-empty{text-align:center;padding:28px;color:#69758c}
</style>
<div class="rea-head"><h2>Result Entry Audit</h2><p>Detailed entries recorded in test_result_audit_trail. Filter by Grace's recorded username or user ID.</p></div>
<div class="rea-tools"><input id="reaUser" placeholder="User name or ID (e.g. Grace)"><input id="reaSearch" placeholder="Search sample, parameter, result, action or date"><button type="button" id="reaApply">Search</button><button type="button" id="reaRefresh">Refresh</button></div>
<div class="rea-table"><table><thead><tr><th>Audit ID</th><th>Timestamp</th><th>User</th><th>Sample ID</th><th>Parameter</th><th>Result type</th><th>Result value</th><th>Action</th><th>Result ID</th></tr></thead><tbody id="reaRows"><tr><td colspan="9" class="rea-empty">Loading…</td></tr></tbody></table></div>
<div class="rea-footer"><span id="reaSummary">Loading…</span><span><button type="button" id="reaPrev">Previous</button> <button type="button" id="reaNext">Next</button></span></div>
<p style="font-size:11px;color:#8490a5">Only entries recorded after the result audit logging was deployed can appear here. This view reads the SQL audit table directly, not the blockchain payload.</p>
</div>
<script>
(function(){
 var root=document.getElementById('resultEntryAudit');if(!root||root.getAttribute('data-ready')==='1')return;root.setAttribute('data-ready','1');
 function el(id){return root.querySelector('#'+id)}var page=1,totalPages=1,requestNo=0;
 function render(rows){var body=el('reaRows');body.innerHTML='';if(!rows.length){var tr=document.createElement('tr');var td=document.createElement('td');td.colSpan=9;td.className='rea-empty';td.textContent='No matching result audit records.';tr.appendChild(td);body.appendChild(tr);return}
 rows.forEach(function(r){var tr=document.createElement('tr');['AuditID','CreatedAt','UserName','SampleID','ParameterName','ResultType','ResultValue','ActionType','resultsID'].forEach(function(k){var td=document.createElement('td');var v=r[k];td.textContent=(v===null||v===undefined||v==='')?'—':String(v);if(k==='UserName'){td.title='User ID: '+String(r.UserID||'');td.textContent=String(r.UserName||'—')+' (ID: '+String(r.UserID||'—')+')'}tr.appendChild(td)});body.appendChild(tr)})}
 function load(){var thisRequest=++requestNo;el('reaRows').innerHTML='<tr><td colspan="9" class="rea-empty">Loading…</td></tr>';var body=new URLSearchParams({page:String(page),user:el('reaUser').value.trim(),search:el('reaSearch').value.trim()});fetch('ajax/result_entry_audit.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8'},body:body.toString()}).then(function(response){if(!response.ok)throw new Error('Request failed: '+response.status);return response.json()}).then(function(data){if(thisRequest!==requestNo)return;if(!data.success)throw new Error(data.message||'Could not load audit records');page=Number(data.page)||1;totalPages=Math.max(1,Number(data.totalPages)||1);render(data.records||[]);el('reaSummary').textContent='Page '+page+' of '+totalPages+' · '+Number(data.total||0)+' records';el('reaPrev').disabled=page<=1;el('reaNext').disabled=page>=totalPages}).catch(function(error){if(thisRequest!==requestNo)return;el('reaRows').innerHTML='<tr><td colspan="9" class="rea-empty"></td></tr>';el('reaRows').querySelector('td').textContent=error.message+' — check the migration and database connection.';el('reaSummary').textContent='Audit query failed'})}
 el('reaApply').addEventListener('click',function(){page=1;load()});el('reaRefresh').addEventListener('click',load);el('reaUser').addEventListener('keydown',function(e){if(e.key==='Enter'){page=1;load()}});el('reaSearch').addEventListener('keydown',function(e){if(e.key==='Enter'){page=1;load()}});el('reaPrev').addEventListener('click',function(){if(page>1){page--;load()}});el('reaNext').addEventListener('click',function(){if(page<totalPages){page++;load()}});load();
})();
</script>